     4→import { useEffect, useMemo, useState } from 'react';
     5→import { useParams, useSearchParams } from 'next/navigation';
     6→import LineItemsTable from '../../components/LineItemsTable';
     7→import type { Quote, LineItem } from '@/lib/airtable';
     8→import { useToast } from '@/components/ui/use-toast';
     9→import { ConfirmationDialog } from '@/components/ui/confirmation-dialog';
    10→import { CTABanner } from '@/components/ui/cta-banner';
    11→import { DollarSign, Trophy, Lock, Plus, User, Mail, MapPin, Building, Home, TreePine } from 'lucide-react';
    12→
    13→const fmtMoney = (n: number | undefined): string =>
    14→  typeof n === 'number' && !Number.isNaN(n)
    15→    ? n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })
    16→    : '-';
    17→
    18→interface QuoteData {
    19→  quote: Quote;
    20→  lineItems: LineItem[];
    21→}
    22→
    23→/**
    24→ * Resilient READ fetch:
    25→ * - Try NEXT_PUBLIC_API_BASE (if present) and the viewer origin
    26→ * - For each base, try common endpoint shapes
    27→ * - Return the first JSON that succeeds
    28→ */
    29→async function fetchQuoteResilient(token: string): Promise<{ data: QuoteData; okUrl: string }> {
    30→  const origin = typeof window !== 'undefined' ? window.location.origin : '';
    31→  const envBase = (process.env.NEXT_PUBLIC_API_BASE || '').replace(/\/$/, '');
    32→  const bases = [envBase, origin].filter(Boolean);
    33→
    34→  const tried: string[] = [];
    35→  for (const base of bases) {
    36→    const urls = [
    37→      `${base}/api/quote/${token}`,
    38→      `${base}/api/quotes/${token}`,
    39→      `${base}/api/quote?token=${encodeURIComponent(token)}`,
    40→    ];
    41→    for (const url of urls) {
    42→      tried.push(url);
    43→      try {
    44→        const res = await fetch(url, { cache: 'no-store' });
    45→        if (!res.ok) continue;
    46→        const data = await res.json();
    47→        // Basic sanity check - a quote payload usually has these fields
    48→        if (data && (Array.isArray(data.lineItems) || data.quote)) {
    49→          return { data, okUrl: url };
    50→        }
    51→      } catch {
    52→        // move on to the next candidate
    53→      }
    54→    }
    55→  }
    56→
    57→  // If everything failed, show the URLs we tried to make troubleshooting easy
    58→  throw new Error(`Failed to fetch quote. Tried:\n- ${tried.join('\n- ')}`);
    59→}
    60→
    61→function fmtPossessive(name: string | undefined): string {
    62→  if (!name) return 'Your';
    63→  return /s$/i.test(name) ? `${name}'` : `${name}'s`;
    64→}
    65→
    66→export default function QuoteViewerPage() {
    67→  const params = useParams();
    68→  const search = useSearchParams();
    69→  const token = params?.token as string;
    70→  const debug = search?.get('debug') === '1';
    71→
    72→  const [loading, setLoading] = useState(true);
    73→  const [quoteData, setQuoteData] = useState<QuoteData | null>(null);
    74→  const [error, setError] = useState<string | null>(null);
    75→  const [loadingItems, setLoadingItems] = useState<Set<string>>(new Set());
    76→  interface DeleteConfirmationState {
    77→    isOpen: boolean;
    78→    itemId: string;
    79→    serviceName: string;
    80→  }
    81→
    82→  const [deleteConfirmation, setDeleteConfirmation] = useState<DeleteConfirmationState>({
    83→    isOpen: false,
    84→    itemId: '',
    85→    serviceName: ''
    86→  });
    87→  const { toast } = useToast();
    88→
    89→  // Calculate savings client-side from line items with chosen frequencies
    90→  const savings = useMemo(() => {
    91→    if (!quoteData?.lineItems) return 0;
    92→    const selectedItems = quoteData.lineItems.filter(item => item.chosenFrequency && item.chosenFrequency > 0);
    93→    const standardTotal = selectedItems.reduce((sum, item) => sum + (item.alaCarteRate * (item.chosenFrequency || 0)), 0);
    94→    const memberTotal = selectedItems.reduce((sum, item) => sum + (item.handldRate * (item.chosenFrequency || 0)), 0);
    95→    return standardTotal - memberTotal;
    96→  }, [quoteData?.lineItems]);
    97→
    98→  // Check if membership is available (3+ services)
    99→  const serviceCount = quoteData?.lineItems?.length || 0;
   100→  const membershipAvailable = serviceCount >= 3;
   101→  const servicesNeeded = Math.max(0, 3 - serviceCount);
   102→
   103→  useEffect(() => {
   104→    let mounted = true;
   105→    (async () => {
   106→      setLoading(true);
   107→      setError(null);
   108→      try {
   109→        if (!token) throw new Error('Missing token in URL.');
   110→        const { data } = await fetchQuoteResilient(token);
   111→        if (!mounted) return;
   112→        setQuoteData(data);
   113→      } catch (e: any) {
   114→        if (mounted) setError(e?.message || 'Failed to load quote');
   115→      } finally {
   116→        if (mounted) setLoading(false);
   117→      }
   118→    })();
   119→    return () => {
   120→      mounted = false;
   121→    };
   122→  }, [token]);
   123→
   124→  const handleFrequencyChange = async (itemId: string, frequency: number) => {
   125→    if (!quoteData) return;
   126→    
   127→    // Capture current state to avoid race conditions
   128→    const currentQuoteData = quoteData;
   129→    const originalItem = currentQuoteData.lineItems.find(item => item.id === itemId);
   130→    const originalFrequency = originalItem?.chosenFrequency;
   131→    
   132→    // Add item to loading state
   133→    setLoadingItems(prev => new Set(prev).add(itemId));
   134→    
   135→    try {
   136→      // Optimistically update the UI using captured state
   137→      const updatedLineItems = currentQuoteData.lineItems.map(item => 
   138→        item.id === itemId ? { ...item, chosenFrequency: frequency } : item
   139→      );
   140→      setQuoteData({ ...currentQuoteData, lineItems: updatedLineItems });
   141→      
   142→      const response = await fetch(`/api/quotes/${token}`, {
   143→        method: 'PUT',
   144→        headers: { 'Content-Type': 'application/json' },
   145→        body: JSON.stringify({
   146→          lineItems: [{ id: itemId, chosenFrequency: frequency }]
   147→        })
   148→      });
   149→      
   150→      if (response.ok) {
   151→        // Success toast
   152→        toast({
   153→          title: "Success",
   154→          description: "Frequency updated successfully",
   155→        });
   156→      } else {
   157→        throw new Error('Failed to update frequency');
   158→      }
   159→    } catch (error) {
   160→      console.error('Failed to update frequency:', error);
   161→      
   162→      // Revert using functional update to prevent race conditions
   163→      setQuoteData(prevData => {
   164→        if (!prevData) return prevData;
   165→        return {
   166→          ...prevData,
   167→          lineItems: prevData.lineItems.map(item => 
   168→            item.id === itemId ? { ...item, chosenFrequency: originalFrequency } : item
   169→          )
   170→        };
   171→      });
   172→      
   173→      // Error toast
   174→      toast({
   175→        title: "Error",
   176→        description: "Failed to update frequency. Please try again.",
   177→        variant: "destructive",
   178→      });
   179→    } finally {
   180→      // Remove item from loading state
   181→      setLoadingItems(prev => {
   182→        const newSet = new Set(prev);
   183→        newSet.delete(itemId);
   184→        return newSet;
   185→      });
   186→    }
   187→  };
   188→
   189→  const handleDeleteItem = (itemId: string) => {
   190→    if (!quoteData) return;
   191→    
   192→    const itemToDelete = quoteData.lineItems.find(item => item.id === itemId);
   193→    const serviceName = itemToDelete?.service || 'Service';
   194→    
   195→    // Show confirmation dialog
   196→    setDeleteConfirmation({
   197→      isOpen: true,
   198→      itemId,
   199→      serviceName
   200→    });
   201→  };
   202→
   203→  const confirmDelete = async () => {
   204→    if (!quoteData) return;
   205→    
   206→    const { itemId, serviceName } = deleteConfirmation;
   207→    
   208→    // Close the confirmation dialog
   209→    setDeleteConfirmation({ isOpen: false, itemId: '', serviceName: '' });
   210→    
   211→    // Capture current state to avoid race conditions
   212→    const currentQuoteData = quoteData;
   213→    const originalLineItems = [...currentQuoteData.lineItems];
   214→    
   215→    // Add item to loading state
   216→    setLoadingItems(prev => new Set(prev).add(itemId));
   217→    
   218→    try {
   219→      // Optimistically remove the item from UI using captured state
   220→      const updatedLineItems = originalLineItems.filter(item => item.id !== itemId);
   221→      setQuoteData({ ...currentQuoteData, lineItems: updatedLineItems });
   222→      
   223→      const response = await fetch(`/api/quotes/${token}`, {
   224→        method: 'DELETE',
   225→        headers: { 'Content-Type': 'application/json' },
   226→        body: JSON.stringify({ itemId })
   227→      });
   228→      
   229→      if (response.ok) {
   230→        const data = await response.json();
   231→        // Update with the fresh data from server
   232→        setQuoteData({ quote: data.quote, lineItems: data.lineItems });
   233→        
   234→        // Success toast
   235→        toast({
   236→          title: "Success",
   237→          description: `${serviceName} removed successfully`,
   238→        });
   239→      } else {
   240→        throw new Error('Failed to delete item');
   241→      }
   242→    } catch (error) {
   243→      console.error('Failed to delete item:', error);
   244→      
   245→      // Revert using captured original state to prevent race conditions
   246→      setQuoteData(prevData => {
   247→        if (!prevData) return prevData;
   248→        // Only revert if the current state still has the item removed
   249→        const currentItemExists = prevData.lineItems.some(item => item.id === itemId);
   250→        if (!currentItemExists) {
   251→          return { ...prevData, lineItems: originalLineItems };
   252→        }
   253→        return prevData;
   254→      });
   255→      
   256→      // Error toast
   257→      toast({
   258→        title: "Error",
   259→        description: `Failed to remove ${serviceName}. Please try again.`,
   260→        variant: "destructive",
   261→      });
   262→    } finally {
   263→      // Remove item from loading state
