     1→// app/api/quotes/[token]/items/route.js
     2→import { NextResponse } from "next/server";
     3→
     4→/**
     5→ * Assumes these Airtable labels (change the strings below if yours differ):
     6→ * Tables:
     7→ *   - "Quote Requests"
     8→ *   - "Quote Line Items"
     9→ *   - "Pricing Rules"
    10→ * Fields:
    11→ *   - On Quote Requests: "Token", "Stories (cache)", "Square Footage (cache)", "Lot Size (cache)"
    12→ *   - On Quote Line Items: "Quote Request" (link), "Service" (single-select),
    13→ *       "Chosen Frequency" (single-select), "Suggested Frequency" (single-select),
    14→ *       "Pricing Rule" (link), (optional) "Notes"
    15→ *   - On Pricing Rules: "Lookup Key"
    16→ *
    17→ * Behavior:
    18→ *   1) Create line item linked to Quote Request, set Service + Frequency (single-selects).
    19→ *   2) Read the quote’s cached values and build the pricing lookup key:
    20→ *        `${service} | ${stories} | ${sqft} | ${lot}`
    21→ *   3) Find the Pricing Rules row by Lookup Key and link it to the new line item.
    22→ *   4) If no frequency was provided, set Chosen Frequency = Suggested Frequency.
    23→ *   5) Return created row + whether Pricing Rule was linked.
    24→ */
    25→
    26→const AIRTABLE_API_KEY = process.env.AIRTABLE_API_KEY;
    27→const AIRTABLE_BASE_ID = process.env.AIRTABLE_BASE_ID;
    28→
    29→// ----- Table names (edit if your labels differ) -----
    30→const QUOTES_TABLE        = process.env.AIRTABLE_TABLE_QUOTES         || "Quote Requests";
    31→const LINE_ITEMS_TABLE    = process.env.AIRTABLE_TABLE_LINE_ITEMS     || "Quote Line Items";
    32→const PRICING_RULES_TABLE = process.env.AIRTABLE_TABLE_PRICING_RULES  || "Pricing Rules";
    33→
    34→// ----- Field names (edit if your labels differ) -----
    35→const QUOTE_TOKEN_FIELD     = process.env.AIRTABLE_FIELD_TOKEN                || "Token";
    36→const QUOTE_STORIES_FIELD   = process.env.AIRTABLE_FIELD_QUOTE_STORIES        || "Stories (cache)";
    37→const QUOTE_SQFT_FIELD      = process.env.AIRTABLE_FIELD_QUOTE_SQFT           || "Square Footage (cache)";
    38→const QUOTE_LOTSIZE_FIELD   = process.env.AIRTABLE_FIELD_QUOTE_LOTSIZE        || "Lot Size (cache)";
    39→
    40→const LI_LINK_TO_QUOTE      = process.env.AIRTABLE_FIELD_LI_QUOTE             || "Quote Request";
    41→const LI_SERVICE_FIELD      = process.env.AIRTABLE_FIELD_LI_SERVICE           || "Service";               // single-select
    42→const LI_CHOSEN_FREQ_FIELD  = process.env.AIRTABLE_FIELD_LI_CHOSEN_FREQ       || "Chosen Frequency";     // single-select
    43→const LI_SUGGESTED_FREQ_FLD = process.env.AIRTABLE_FIELD_LI_SUGGESTED_FREQ    || "Suggested Frequency";  // single-select (or lookup)
    44→const LI_PRICING_RULE_FIELD = process.env.AIRTABLE_FIELD_LI_PRICING_RULE      || "Pricing Rule";         // link
    45→const LI_NOTES_FIELD        = process.env.AIRTABLE_FIELD_LI_NOTES             || "Notes";                // optional
    46→
    47→const PR_LOOKUP_KEY_FIELD   = process.env.AIRTABLE_FIELD_PR_LOOKUP_KEY        || "Lookup Key";
    48→
    49→function bad(status, msg) {
    50→  return NextResponse.json({ error: msg }, { status });
    51→}
    52→
    53→async function at(path, options = {}) {
    54→  const res = await fetch(`https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/${path}`, {
    55→    ...options,
    56→    headers: {
    57→      Authorization: `Bearer ${AIRTABLE_API_KEY}`,
    58→      "Content-Type": "application/json",
    59→      ...(options.headers || {}),
    60→    },
    61→  });
    62→  const data = await res.json();
    63→  return { ok: res.ok, status: res.status, data };
    64→}
    65→
    66→// Resolve Quote Request record id by token
    67→async function quoteIdFromToken(token) {
    68→  const filter = encodeURIComponent(`{${QUOTE_TOKEN_FIELD}} = "${token}"`);
    69→  const { ok, status, data } = await at(
    70→    `${encodeURIComponent(QUOTES_TABLE)}?filterByFormula=${filter}&maxRecords=1`
    71→  );
    72→  if (!ok) throw new Error(`Airtable ${status}: ${data?.error?.message || "Quote lookup failed"}`);
    73→  return data?.records?.[0]?.id || null;
    74→}
    75→
    76→// Read caches from Quote Request (Stories/SqFt/Lot)
    77→async function fetchQuoteCaches(quoteId) {
    78→  const { ok, status, data } = await at(`${encodeURIComponent(QUOTES_TABLE)}/${quoteId}`);
    79→  if (!ok) throw new Error(`Airtable ${status}: ${data?.error?.message || "Quote read failed"}`);
    80→  const f = data?.fields || {};
    81→  return {
    82→    stories: f[QUOTE_STORIES_FIELD] ?? "Any",
    83→    sqft:    f[QUOTE_SQFT_FIELD]    ?? "Any",
    84→    lot:     f[QUOTE_LOTSIZE_FIELD] ?? "Any",
    85→  };
    86→}
    87→
    88→function buildLookupKey(service, caches) {
    89→  // mirrors your Airtable formula for Lookup Key (cache)
    90→  return `${service} | ${caches.stories} | ${caches.sqft} | ${caches.lot}`;
    91→}
    92→
    93→async function findPricingRuleIdByLookupKey(lookupKey) {
    94→  const filter = encodeURIComponent(`{${PR_LOOKUP_KEY_FIELD}} = "${lookupKey}"`);
    95→  const { ok, status, data } = await at(
    96→    `${encodeURIComponent(PRICING_RULES_TABLE)}?filterByFormula=${filter}&maxRecords=1`
    97→  );
    98→  if (!ok) throw new Error(`Airtable ${status}: ${data?.error?.message || "Pricing Rules query failed"}`);
    99→  return data?.records?.[0]?.id || null;
   100→}
   101→
   102→// Normalize a Suggested Frequency value that might be string/object/array
   103→function normalizeSuggested(val) {
   104→  if (!val) return null;
   105→  if (typeof val === "string") return val;
   106→  if (Array.isArray(val)) {
   107→    // lookups sometimes return arrays—take first stringy thing
   108→    const first = val[0];
   109→    if (!first) return null;
   110→    if (typeof first === "string") return first;
   111→    if (typeof first === "object" && first.name) return first.name;
   112→    return null;
   113→  }
   114→  if (typeof val === "object" && val.name) return val.name;
   115→  return null;
   116→}
   117→
   118→export async function POST(req, { params }) {
   119→  try {
   120→    if (!AIRTABLE_API_KEY || !AIRTABLE_BASE_ID) return bad(500, "Missing Airtable credentials");
   121→
   122→    const tokenFromUrl = params?.token;
   123→    const body = await req.json().catch(() => ({}));
   124→
   125→    // Expected body:
   126→    // { serviceName: "Gutter Cleaning", frequency?: "Monthly", useSuggested?: boolean, notes?: string, quoteRecordId?: "rec..." }
   127→    const serviceName = body?.serviceName || body?.service;
   128→    if (!serviceName) return bad(400, "Missing serviceName");
   129→
   130→    // Determine target quote
   131→    let quoteId = body?.quoteRecordId || null;
   132→    if (!quoteId) {
   133→      if (!tokenFromUrl) return bad(400, "Missing quoteRecordId and URL token");
   134→      quoteId = await quoteIdFromToken(tokenFromUrl);
   135→      if (!quoteId) return bad(400, "Could not resolve quoteRecordId from token");
   136→    }
   137→
   138→    const frequency    = body?.frequency || null;
   139→    const useSuggested = Boolean(body?.useSuggested);
   140→    const notes        = body?.notes ?? undefined;
   141→
   142→    // 1) CREATE line item (Service & Frequency are SINGLE-SELECTS → pass plain strings)
   143→    const createFields = {
   144→      [LI_LINK_TO_QUOTE]: [quoteId],     // link field expects array of record IDs
   145→      [LI_SERVICE_FIELD]: serviceName,   // single-select → string (typecast true)
   146→    };
   147→    if (frequency) {
   148→      const freqField = useSuggested ? LI_SUGGESTED_FREQ_FLD : LI_CHOSEN_FREQ_FIELD;
   149→      createFields[freqField] = frequency; // single-select → string (typecast true)
   150→    }
   151→    if (notes) createFields[LI_NOTES_FIELD] = notes;
   152→
   153→    const createPayload = { records: [{ fields: createFields }], typecast: true };
   154→    const createRes = await at(`${encodeURIComponent(LINE_ITEMS_TABLE)}`, {
   155→      method: "POST",
   156→      body: JSON.stringify(createPayload),
   157→    });
   158→    if (!createRes.ok) {
