'use client';

import React from 'react';
import { X, Plus, Loader2 } from 'lucide-react';

interface ServiceSelectionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectService: (serviceName: string) => void;
  services: string[];
  isLoading: boolean;
  error: string | null;
  isAddingService?: boolean;
}

export function ServiceSelectionModal({
  isOpen,
  onClose,
  onSelectService,
  services,
  isLoading,
  error,
  isAddingService = false
}: ServiceSelectionModalProps) {
  if (!isOpen) return null;

  const handleServiceSelect = (serviceName: string) => {
    if (!isAddingService) {
      onSelectService(serviceName);
    }
  };

  const handleBackdropClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget && !isAddingService) {
      onClose();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape' && !isAddingService) {
      onClose();
    }
  };

  return (
    <>
      {/* Backdrop */}
      <div 
        className="fixed inset-0 bg-black bg-opacity-50 z-40 transition-opacity"
        onClick={handleBackdropClick}
      />

      {/* Modal */}
      <div 
        className="fixed inset-0 z-50 flex items-center justify-center p-4"
        onKeyDown={handleKeyDown}
        tabIndex={-1}
      >
        <div className="bg-white rounded-xl shadow-2xl max-w-md w-full max-h-[80vh] overflow-hidden transform transition-all">
          {/* Header */}
          <div className="flex items-center justify-between p-6 border-b border-gray-200">
            <h3 className="text-lg font-semibold text-gray-900">
              Add Service
            </h3>
            <button
              onClick={onClose}
              disabled={isAddingService}
              className="text-gray-400 hover:text-gray-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <X className="h-5 w-5" />
            </button>
          </div>

          {/* Content */}
          <div className="p-6 overflow-y-auto max-h-96">
            {isLoading ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="h-6 w-6 animate-spin text-brand-navy mr-2" />
                <span className="text-gray-600">Loading services...</span>
              </div>
            ) : error ? (
              <div className="text-center py-8">
                <p className="text-red-600 mb-4">{error}</p>
                <button
                  onClick={onClose}
                  className="text-sm px-4 py-2 rounded-lg border border-gray-300 text-gray-700 bg-gray-100 hover:bg-gray-200 transition-colors"
                >
                  Close
                </button>
              </div>
            ) : services.length === 0 ? (
              <div className="text-center py-8">
                <p className="text-gray-600 mb-4">No services available</p>
                <button
                  onClick={onClose}
                  className="text-sm px-4 py-2 rounded-lg border border-gray-300 text-gray-700 bg-gray-100 hover:bg-gray-200 transition-colors"
                >
                  Close
                </button>
              </div>
            ) : (
              <div className="space-y-2">
                <p className="text-sm text-gray-600 mb-4">
                  Select a service to add to your quote:
                </p>
                {services.map((service) => (
                  <button
                    key={service}
                    onClick={() => handleServiceSelect(service)}
                    disabled={isAddingService}
                    className={`w-full text-left p-3 rounded-lg border border-gray-200 hover:border-brand-navy hover:bg-brand-light-cream transition-colors flex items-center justify-between group ${
                      isAddingService ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'
                    }`}
                  >
                    <span className="font-medium text-brand-navy">{service}</span>
                    <Plus className="h-4 w-4 text-gray-400 group-hover:text-brand-navy transition-colors" />
                  </button>
                ))}
              </div>
            )}
          </div>

          {isAddingService && (
            <div className="absolute inset-0 bg-white/50 flex items-center justify-center">
              <div className="bg-white rounded-lg shadow-lg p-4 flex items-center gap-3">
                <Loader2 className="h-5 w-5 animate-spin text-brand-navy" />
                <span className="text-brand-navy font-medium">Adding service...</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </>
  );
}

