import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ServiceSelectionModal } from '../service-selection-modal';

// Mock lucide-react
jest.mock('lucide-react', () => ({
  X: ({ className }: { className?: string }) => (
    <div data-testid="close-icon" className={className}>X</div>
  ),
  Plus: ({ className }: { className?: string }) => (
    <div data-testid="plus-icon" className={className}>+</div>
  ),
  Loader2: ({ className }: { className?: string }) => (
    <div data-testid="loader" className={className}>Loading...</div>
  ),
}));

describe('ServiceSelectionModal', () => {
  const mockServices = ['Window Washing', 'Gutter Cleaning', 'Pressure Washing - Driveway & Patio'];
  const mockOnClose = jest.fn();
  const mockOnSelectService = jest.fn();

  const defaultProps = {
    isOpen: true,
    onClose: mockOnClose,
    onSelectService: mockOnSelectService,
    services: mockServices,
    isLoading: false,
    error: null,
    isAddingService: false,
  };

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('Rendering', () => {
    it('renders nothing when isOpen is false', () => {
      const { container } = render(
        <ServiceSelectionModal {...defaultProps} isOpen={false} />
      );
      expect(container.firstChild).toBeNull();
    });

    it('renders modal when isOpen is true', () => {
      render(<ServiceSelectionModal {...defaultProps} />);

      expect(screen.getByText('Add Service')).toBeInTheDocument();
      expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      expect(screen.getByTestId('close-icon')).toBeInTheDocument();
    });

    it('renders all services as buttons', () => {
      render(<ServiceSelectionModal {...defaultProps} />);

      mockServices.forEach(service => {
        expect(screen.getByText(service)).toBeInTheDocument();
      });
    });

    it('renders plus icons for each service', () => {
      render(<ServiceSelectionModal {...defaultProps} />);

      const plusIcons = screen.getAllByTestId('plus-icon');
      expect(plusIcons).toHaveLength(mockServices.length);
    });
  });

  describe('Loading State', () => {
    it('displays loading spinner when isLoading is true', () => {
      render(<ServiceSelectionModal {...defaultProps} isLoading={true} />);

      expect(screen.getByTestId('loader')).toBeInTheDocument();
      expect(screen.getByText('Loading services...')).toBeInTheDocument();
      expect(screen.queryByText('Select a service to add to your quote:')).not.toBeInTheDocument();
    });

    it('does not display services while loading', () => {
      render(<ServiceSelectionModal {...defaultProps} isLoading={true} />);

      mockServices.forEach(service => {
        expect(screen.queryByText(service)).not.toBeInTheDocument();
      });
    });
  });

  describe('Error State', () => {
    it('displays error message when error is present', () => {
      const errorMessage = 'Failed to load services';
      render(<ServiceSelectionModal {...defaultProps} error={errorMessage} />);

      expect(screen.getByText(errorMessage)).toBeInTheDocument();
      expect(screen.getByText('Close')).toBeInTheDocument();
      expect(screen.queryByText('Select a service to add to your quote:')).not.toBeInTheDocument();
    });

    it('does not display services when error is present', () => {
      render(<ServiceSelectionModal {...defaultProps} error="Some error" />);

      mockServices.forEach(service => {
        expect(screen.queryByText(service)).not.toBeInTheDocument();
      });
    });
  });

  describe('Empty State', () => {
    it('displays no services message when services array is empty', () => {
      render(<ServiceSelectionModal {...defaultProps} services={[]} />);

      expect(screen.getByText('No services available')).toBeInTheDocument();
      expect(screen.getByText('Close')).toBeInTheDocument();
    });
  });

  describe('User Interactions', () => {
    it('calls onClose when close button is clicked', async () => {
      const user = userEvent.setup();
      render(<ServiceSelectionModal {...defaultProps} />);

      const closeButton = screen.getByTestId('close-icon').parentElement!;
      await user.click(closeButton);

      expect(mockOnClose).toHaveBeenCalledTimes(1);
    });

    it('calls onClose when backdrop is clicked', async () => {
      const user = userEvent.setup();
      render(<ServiceSelectionModal {...defaultProps} />);

      // Find backdrop by looking for the div with the backdrop class
      const backdrop = document.querySelector('.fixed.inset-0.bg-black.bg-opacity-50')!;
      await user.click(backdrop);

      expect(mockOnClose).toHaveBeenCalledTimes(1);
    });

    it('calls onSelectService when service button is clicked', async () => {
      const user = userEvent.setup();
      render(<ServiceSelectionModal {...defaultProps} />);

      const serviceButton = screen.getByText(mockServices[0]);
      await user.click(serviceButton);

      expect(mockOnSelectService).toHaveBeenCalledWith(mockServices[0]);
    });

    it('calls onClose when Escape key is pressed', async () => {
      const user = userEvent.setup();
      render(<ServiceSelectionModal {...defaultProps} />);

      await user.keyboard('[Escape]');

      expect(mockOnClose).toHaveBeenCalledTimes(1);
    });
  });

  describe('Adding Service State', () => {
    it('disables all interactions when isAddingService is true', () => {
      render(<ServiceSelectionModal {...defaultProps} isAddingService={true} />);

      // Close button should be disabled
      const closeButton = screen.getByTestId('close-icon').parentElement!;
      expect(closeButton).toHaveAttribute('disabled');

      // Service buttons should be disabled
      mockServices.forEach(service => {
        const serviceButton = screen.getByText(service).closest('button')!;
        expect(serviceButton).toHaveAttribute('disabled');
        expect(serviceButton).toHaveClass('opacity-50 cursor-not-allowed');
      });
    });

    it('shows adding service overlay when isAddingService is true', () => {
      render(<ServiceSelectionModal {...defaultProps} isAddingService={true} />);

      expect(screen.getByText('Adding service...')).toBeInTheDocument();
      expect(screen.getByTestId('loader')).toBeInTheDocument();
    });

    it('does not call onClose when backdrop is clicked while adding service', async () => {
      const user = userEvent.setup();
      render(<ServiceSelectionModal {...defaultProps} isAddingService={true} />);

      const backdrop = document.querySelector('.fixed.inset-0.bg-black.bg-opacity-50')!;
      await user.click(backdrop);

      expect(mockOnClose).not.toHaveBeenCalled();
    });

    it('does not call onSelectService when service is clicked while adding service', async () => {
      const user = userEvent.setup();
      render(<ServiceSelectionModal {...defaultProps} isAddingService={true} />);

      const serviceButton = screen.getByText(mockServices[0]).closest('button')!;
      await user.click(serviceButton);

      expect(mockOnSelectService).not.toHaveBeenCalled();
    });
  });
});

