import { renderHook, waitFor } from '@testing-library/react';
import { useServices } from '../useServices';

// Mock fetch globally
const mockFetch = jest.fn();
global.fetch = mockFetch;

describe('useServices', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockFetch.mockReset();
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe('Successful fetch', () => {
    it('should fetch services successfully', async () => {
      const mockServices = ['Window Washing', 'Gutter Cleaning', 'Pressure Washing'];
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services: mockServices }),
      });

      const { result } = renderHook(() => useServices());

      // Initially loading
      expect(result.current.isLoading).toBe(true);
      expect(result.current.services).toEqual([]);
      expect(result.current.error).toBe(null);

      // Wait for fetch to complete
      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.services).toEqual(mockServices);
      expect(result.current.error).toBe(null);
      expect(mockFetch).toHaveBeenCalledWith('/api/services', { cache: 'no-store' });
    });

    it('should handle empty services array', async () => {
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services: [] }),
      });

      const { result } = renderHook(() => useServices());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.services).toEqual([]);
      expect(result.current.error).toBe(null);
    });

    it('should handle missing services property', async () => {
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({}),
      });

      const { result } = renderHook(() => useServices());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.services).toEqual([]);
      expect(result.current.error).toBe(null);
    });
  });

  describe('Error handling', () => {
    it('should handle HTTP error responses', async () => {
      mockFetch.mockResolvedValueOnce({
        ok: false,
        status: 500,
      });

      const { result } = renderHook(() => useServices());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.services).toEqual([]);
      expect(result.current.error).toBe('Failed to fetch services: 500');
    });

    it('should handle API error responses', async () => {
      const errorMessage = 'Airtable connection failed';
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ error: errorMessage }),
      });

      const { result } = renderHook(() => useServices());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.services).toEqual([]);
      expect(result.current.error).toBe(errorMessage);
    });

    it('should handle network errors', async () => {
      mockFetch.mockRejectedValueOnce(new Error('Network error'));

      const { result } = renderHook(() => useServices());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.services).toEqual([]);
      expect(result.current.error).toBe('Network error');
    });

    it('should handle JSON parsing errors', async () => {
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => {
          throw new Error('Invalid JSON');
        },
      });

      const { result } = renderHook(() => useServices());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.services).toEqual([]);
      expect(result.current.error).toBe('Invalid JSON');
    });

    it('should handle unknown errors', async () => {
      mockFetch.mockRejectedValueOnce('Unknown error');

      const { result } = renderHook(() => useServices());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.services).toEqual([]);
      expect(result.current.error).toBe('Failed to load services');
    });
  });

  describe('Refetch functionality', () => {
    it('should refetch services when refetch is called', async () => {
      const firstServices = ['Service 1'];
      const secondServices = ['Service 1', 'Service 2'];

      // First fetch
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services: firstServices }),
      });

      const { result } = renderHook(() => useServices());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.services).toEqual(firstServices);
      expect(mockFetch).toHaveBeenCalledTimes(1);

      // Second fetch
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services: secondServices }),
      });

      result.current.refetch();

      // Wait for refetch to complete
      await waitFor(() => {
        expect(result.current.services).toEqual(secondServices);
      });

      expect(result.current.isLoading).toBe(false);
      expect(mockFetch).toHaveBeenCalledTimes(2);
    });

    it('should reset error state when refetching', async () => {
      // First fetch fails
      mockFetch.mockResolvedValueOnce({
        ok: false,
        status: 500,
      });

      const { result } = renderHook(() => useServices());

      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });

      expect(result.current.error).toBe('Failed to fetch services: 500');

      // Second fetch succeeds
      const services = ['Service 1'];
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services }),
      });

      result.current.refetch();

      // Wait for refetch to complete
      await waitFor(() => {
        expect(result.current.services).toEqual(services);
      });

      expect(result.current.isLoading).toBe(false);
      expect(result.current.error).toBe(null);
    });
  });
});

