        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 1,
            quoteId: 'Q-001',
          },
          {
            id: 'rec789',
