import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import QuoteViewerPage from '../page';
import { useParams, useSearchParams } from 'next/navigation';

// Mock Next.js navigation
jest.mock('next/navigation', () => ({
  useParams: jest.fn(),
  useSearchParams: jest.fn(),
}));

// Mock the Toaster component
jest.mock('@/components/ui/use-toast', () => ({
  useToast: () => ({
    toast: jest.fn(),
  }),
}));

// Mock CTABanner component
jest.mock('@/components/ui/cta-banner', () => ({
  CTABanner: ({ message }: { message: string }) => (
    <div data-testid="cta-banner">{message}</div>
  ),
}));

// Mock Lucide React icons
jest.mock('lucide-react', () => ({
  DollarSign: () => <div data-testid="dollar-icon">$</div>,
  Trophy: () => <div data-testid="trophy-icon">🏆</div>,
  Lock: () => <div data-testid="lock-icon">🔒</div>,
  Plus: () => <div data-testid="plus-icon">+</div>,
  User: () => <div data-testid="user-icon">👤</div>,
  Mail: () => <div data-testid="mail-icon">📧</div>,
  MapPin: () => <div data-testid="map-icon">📍</div>,
  Building: () => <div data-testid="building-icon">🏢</div>,
  Home: () => <div data-testid="home-icon">🏠</div>,
  TreePine: () => <div data-testid="tree-icon">🌲</div>,
  Loader2: ({ className }: { className?: string }) => (
    <div data-testid="loader" className={className}>Loading...</div>
  ),
  X: () => <div data-testid="close-icon">X</div>,
}));

// Mock fetch globally
const mockFetch = jest.fn();
global.fetch = mockFetch;

describe('Duplicate Service Prevention', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockFetch.mockReset();

    // Mock navigation hooks
    (useParams as jest.Mock).mockReturnValue({ token: 'test-token' });
    (useSearchParams as jest.Mock).mockReturnValue({
      get: jest.fn().mockReturnValue(null),
    });
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe('Service Filtering Based on Existing Services', () => {
    it('should not show services that are already in the quote', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning', 'Pressure Washing', 'Handyman'];
      const existingServices = ['Window Washing', 'Handyman'];
      const availableServices = ['Gutter Cleaning', 'Pressure Washing'];

      // Mock quote data with existing services
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 200,
          handldTotal: 140,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 1,
            quoteId: 'Q-001',
          },
          {
            id: 'rec789',
            service: 'Handyman',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 2,
            quoteId: 'Q-001',
          },
        ],
      };

      // Mock fetch with URL-specific responses
      mockFetch.mockImplementation((url: string) => {
        if (url.includes('/api/quotes/')) {
          console.log('Mock fetch called for quote data:', url);
          return Promise.resolve({
            ok: true,
            json: async () => {
              console.log('Returning quote data:', mockQuoteData);
              return mockQuoteData;
            },
          });
        } else if (url.includes('/api/services')) {
          console.log('Mock fetch called for services data:', url);
          return Promise.resolve({
            ok: true,
            json: async () => ({ services: allServices }),
          });
        }
        return Promise.reject(new Error(`Unhandled URL: ${url}`));
      });

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Verify existing services are displayed
      expect(screen.getByText('Window Washing')).toBeInTheDocument();
      expect(screen.getByText('Handyman')).toBeInTheDocument();

      // Open the service selection modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Debug: Log what service buttons are actually rendered in the modal
      const modalButtons = document.querySelectorAll('button span.font-medium.text-brand-navy');
      console.log('Services shown in modal:', Array.from(modalButtons).map(btn => btn.textContent));

      // Should only show available services (not existing ones)
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      expect(screen.getByText('Pressure Washing')).toBeInTheDocument();

      // Should NOT show existing services in the modal - check specifically within the modal
      const modalContainer = document.querySelector('.fixed.inset-0.z-50');
      if (modalContainer) {
        const modalServiceButtons = modalContainer.querySelectorAll('button span.font-medium.text-brand-navy');
        const modalServices = Array.from(modalServiceButtons).map(btn => btn.textContent);
        console.log('Services specifically in modal:', modalServices);

        expect(modalServices).not.toContain('Window Washing');
        expect(modalServices).not.toContain('Handyman');
        expect(modalServices).toContain('Gutter Cleaning');
        expect(modalServices).toContain('Pressure Washing');
      } else {
        throw new Error('Modal container not found');
      }
    });

    it('should show "No services available" when all services are already added', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning'];

      // Mock quote data with all available services
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 200,
          handldTotal: 140,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 1,
            quoteId: 'Q-001',
          },
          {
            id: 'rec789',
            service: 'Gutter Cleaning',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 1,
            quoteId: 'Q-001',
          },
        ],
      };

      // Mock fetch with URL-specific responses
      mockFetch.mockImplementation((url: string) => {
        if (url.includes('/api/quotes/')) {
          return Promise.resolve({
            ok: true,
            json: async () => mockQuoteData,
          });
        } else if (url.includes('/api/services')) {
          return Promise.resolve({
            ok: true,
            json: async () => ({ services: allServices }),
          });
        }
        return Promise.reject(new Error(`Unhandled URL: ${url}`));
      });

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open the service selection modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('No services available')).toBeInTheDocument();
      });

      // Should show the close button
      expect(screen.getByText('Close')).toBeInTheDocument();
    });

    it('should update available services after successfully adding a service', async () => {
      const user = userEvent.setup();
      const allServices = ['Window Washing', 'Gutter Cleaning', 'Pressure Washing'];

      // Initial quote with one service
      const initialQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 100,
          handldTotal: 70,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 1,
            quoteId: 'Q-001',
          },
        ],
      };

      // Updated quote after adding service
      const updatedQuoteData = {
        ...initialQuoteData,
        lineItems: [
          ...initialQuoteData.lineItems,
          {
            id: 'rec789',
            service: 'Gutter Cleaning',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 1,
            quoteId: 'Q-001',
          },
        ],
      };

      // Mock initial quote fetch
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => initialQuoteData,
      });

      // Mock initial services fetch (should exclude Window Washing)
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services: allServices }),
      });

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal first time
      let addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should show Gutter Cleaning and Pressure Washing, but not Window Washing
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      expect(screen.getByText('Pressure Washing')).toBeInTheDocument();

      // Mock add service API call
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          ok: true,
          created: { id: 'rec789' },
          pricingRuleLinked: true,
        }),
      });

      // Mock refetch quote data
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => updatedQuoteData,
      });

      // Add Gutter Cleaning
      const gutterCleaningButton = screen.getByText('Gutter Cleaning');
      await user.click(gutterCleaningButton);

      // Wait for modal to close and service to be added
      await waitFor(() => {
        expect(screen.queryByText('Select a service to add to your quote:')).not.toBeInTheDocument();
      });

      // Verify Gutter Cleaning now appears in the line items
      await waitFor(() => {
        expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      });

      // Mock services fetch for second modal opening (should now exclude both existing services)
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services: allServices }),
      });

      // Open modal again
      addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Now should only show Pressure Washing (Window Washing and Gutter Cleaning should be filtered out)
      expect(screen.getByText('Pressure Washing')).toBeInTheDocument();
      expect(screen.queryByText('Gutter Cleaning')).not.toBeInTheDocument();
    });

    it('should handle case-sensitive service matching correctly', async () => {
      const allServices = ['Window Washing', 'window washing', 'WINDOW WASHING'];

      // Mock quote with one variation
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 100,
          handldTotal: 70,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing', // Exact case match
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 1,
            quoteId: 'Q-001',
          },
        ],
      };

      // Mock quote fetch from /api/quotes/[token]
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => mockQuoteData,
      });

      // Mock services fetch
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services: allServices }),
      });

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should show the other case variations but not the exact match
      expect(screen.getByText('window washing')).toBeInTheDocument();
      expect(screen.getByText('WINDOW WASHING')).toBeInTheDocument();
      // The exact case match should be filtered out and not appear in the modal
      const windowWashingButtons = screen.queryAllByText('Window Washing');
      // Only the one in the line items table should exist, not in the modal
      expect(windowWashingButtons.length).toBe(1);
    });
  });

  describe('Edge Cases', () => {
    it('should handle empty line items correctly', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning'];

      // Mock quote with no line items
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 0,
          handldTotal: 0,
        },
        lineItems: [],
      };

      // Mock quote fetch from /api/quotes/[token]
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => mockQuoteData,
      });

      // Mock services fetch
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services: allServices }),
      });

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should show all services since none are existing
      expect(screen.getByText('Window Washing')).toBeInTheDocument();
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
    });

    it('should handle undefined line items correctly', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning'];

      // Mock quote with undefined line items
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 0,
          handldTotal: 0,
        },
        lineItems: undefined,
      };

      // Mock quote fetch from /api/quotes/[token]
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => mockQuoteData,
      });

      // Mock services fetch
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ services: allServices }),
      });

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should show all services since line items is undefined
      expect(screen.getByText('Window Washing')).toBeInTheDocument();
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
    });
  });
});

