      const noServiceData = {
        ...mockQuoteDataWithThreeServices,
        lineItems: [],
      };

      (fetch as jest.Mock).mockResolvedValueOnce({
        ok: true,
        json: async () => noServiceData,
      });

      render(<QuoteViewerPage />);

      await waitFor(() => {
        // CTA banner should be present
        expect(screen.getByTestId('cta-banner')).toBeInTheDocument();
      });
    });
  });
});

