import React from 'react';
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import QuoteViewerPage from '../page';
import { useToast } from '@/components/ui/use-toast';
import { setupFetchMocks, setupUpdateFetchMocks, setupErrorFetchMocks } from './test-helpers';

// Mock dependencies
jest.mock('next/navigation', () => ({
  useParams: jest.fn(),
  useSearchParams: jest.fn(),
}));

jest.mock('@/components/ui/use-toast', () => ({
  useToast: jest.fn(),
}));

jest.mock('../../../components/LineItemsTable', () => {
  return function MockLineItemsTable({ 
    lineItems, 
    loadingItems, 
    onFrequencyChange,
    onRemoveItem
  }: any) {
    return (
      <div data-testid="line-items-table">
        {lineItems.map((item: any) => (
          <div key={item.id}>
            <span>{item.service}</span>
            <button 
              onClick={() => onFrequencyChange?.(item.id, 3)}
              disabled={loadingItems?.has(item.id)}
            >
              Change Frequency
            </button>
            <button 
              onClick={() => onRemoveItem?.(item.id)}
              disabled={loadingItems?.has(item.id)}
            >
              Remove
            </button>
            {loadingItems?.has(item.id) && <span>Loading...</span>}
          </div>
        ))}
      </div>
    );
  };
});

jest.mock('@/components/ui/cta-banner', () => ({
  CTABanner: ({ message }: { message: string }) => <div data-testid="cta-banner">{message}</div>,
}));

// Mock fetch
global.fetch = jest.fn();

describe('QuoteViewerPage - Membership Requirements', () => {
  const mockToast = jest.fn();
  const mockQuoteDataWithTwoServices = {
    quote: {
      id: 'rec123',
      quoteId: 'Q-001',
      firstName: 'John',
