import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import LineItemsTable from '@/app/components/LineItemsTable';
import QuoteViewerPage from '@/app/q/[token]/page';
import { NextRequest } from 'next/server';
import { DELETE } from '@/app/api/quotes/[token]/route';

// Mock NextResponse
jest.mock('next/server', () => ({
  NextRequest: jest.fn(),
  NextResponse: {
    json: (data: any, init?: any) => {
      const response = new Response(JSON.stringify(data), init);
      response.json = async () => data;
      Object.defineProperty(response, 'status', {
        get: () => init?.status || 200
      });
      return response;
    }
  }
}));

// Mock the toast hook
const mockToast = jest.fn();
jest.mock('@/components/ui/use-toast', () => ({
  useToast: () => ({ toast: mockToast })
}));

// Mock the confirmation dialog
jest.mock('@/components/ui/confirmation-dialog', () => ({
  ConfirmationDialog: ({ isOpen, onConfirm, onCancel }: any) => {
    if (!isOpen) return null;
    return (
      <div data-testid="confirmation-dialog">
        <button onClick={onConfirm} data-testid="confirm-button">Confirm</button>
        <button onClick={onCancel} data-testid="cancel-button">Cancel</button>
      </div>
    );
  }
}));

// Mock the Airtable functions
jest.mock('@/lib/airtable', () => ({
  deleteLineItem: jest.fn(),
  getQuoteByToken: jest.fn(),
  updateLineItems: jest.fn(),
  findQuoteByToken: jest.fn(),
  updateQuote: jest.fn()
}));

// Mock useParams
jest.mock('next/navigation', () => ({
  ...jest.requireActual('next/navigation'),
  useParams: () => ({ token: 'test-token' }),
  useSearchParams: () => new URLSearchParams()
}));

describe('Delete Line Item Functionality', () => {
  const mockLineItems = [
    {
      id: 'item1',
      quoteId: 'Q123',
      service: 'Lawn Mowing',
      chosenFrequency: 2,
      alaCarteRate: 100,
      handldRate: 70
    },
    {
      id: 'item2',
      quoteId: 'Q123', 
      service: 'Tree Trimming',
      chosenFrequency: 1,
      alaCarteRate: 200,
      handldRate: 140
    }
  ];

  const mockQuote = {
    id: 'quote1',
    quoteId: 'Q123',
    firstName: 'John',
    lastName: 'Doe',
    email: 'john@example.com',
    city: 'Austin',
    token: 'test-token'
  };

  beforeEach(() => {
    jest.clearAllMocks();
    mockToast.mockClear();
    global.fetch = jest.fn();
  });

  describe('LineItemsTable Component', () => {
    it('should call onRemoveItem when remove button is clicked', () => {
      const mockOnRemoveItem = jest.fn();

      render(
        <LineItemsTable
          lineItems={mockLineItems}
          onRemoveItem={mockOnRemoveItem}
        />
      );

      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      expect(mockOnRemoveItem).toHaveBeenCalledWith('item1');
    });

    it('should disable row when item is in loading state', () => {
      const loadingItems = new Set(['item1']);

      render(
        <LineItemsTable
          lineItems={mockLineItems}
          loadingItems={loadingItems}
          onRemoveItem={jest.fn()}
        />
      );

      const removeButtons = screen.getAllByText('Remove');
      expect(removeButtons[0]).toBeDisabled();
      expect(removeButtons[1]).not.toBeDisabled();
    });

    it('should show loading spinner for items being deleted', () => {
      const loadingItems = new Set(['item1']);

      render(
        <LineItemsTable
          lineItems={mockLineItems}
          loadingItems={loadingItems}
          onRemoveItem={jest.fn()}
        />
      );

      // Check for loading state (opacity change)
      const rows = screen.getByText('Lawn Mowing').closest('div.p-4');
      expect(rows).toHaveClass('opacity-60');
    });
  });

  describe('Delete API Endpoint', () => {
    it('should delete item and return updated data', async () => {
      const { deleteLineItem, getQuoteByToken } = require('@/lib/airtable');

      deleteLineItem.mockResolvedValue(undefined);
      getQuoteByToken.mockResolvedValue({
        quote: mockQuote,
        lineItems: [mockLineItems[1]] // Only second item remains
      });

      // Create a mock request object
      const mockRequest = {
        json: jest.fn().mockResolvedValue({ itemId: 'item1' })
      } as unknown as NextRequest;

      const response = await DELETE(mockRequest, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(deleteLineItem).toHaveBeenCalledWith('item1');
      expect(getQuoteByToken).toHaveBeenCalledWith('test-token');
      expect(data.ok).toBe(true);
      expect(data.lineItems).toHaveLength(1);
      expect(data.lineItems[0].id).toBe('item2');
    });

    it('should return error when itemId is missing', async () => {
      const mockRequest = {
        json: jest.fn().mockResolvedValue({})
      } as unknown as NextRequest;

      const response = await DELETE(mockRequest, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(response.status).toBe(400);
      expect(data.error).toBe('Item ID is required');
    });

    it('should handle deletion errors', async () => {
      const { deleteLineItem } = require('@/lib/airtable');

      deleteLineItem.mockRejectedValue(new Error('Deletion failed'));

      const mockRequest = {
        json: jest.fn().mockResolvedValue({ itemId: 'item1' })
      } as unknown as NextRequest;

      const response = await DELETE(mockRequest, { params: { token: 'test-token' } });
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data.error).toBe('Deletion failed');
    });
  });

  describe('Quote Viewer Page Integration', () => {
    beforeEach(() => {
      (global.fetch as jest.Mock) = jest.fn()
        .mockResolvedValueOnce({
          ok: true,
          json: async () => ({
            quote: mockQuote,
            lineItems: mockLineItems
          })
        });
    });

    it('should handle successful deletion with confirmation and toast notification', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Click remove button - should show confirmation dialog
      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      // Verify confirmation dialog appears
      await waitFor(() => {
        expect(screen.getByTestId('confirmation-dialog')).toBeInTheDocument();
      });

      // Mock successful deletion
      (global.fetch as jest.Mock).mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          ok: true,
          quote: mockQuote,
          lineItems: [mockLineItems[1]] // Only second item remains
        })
      });

      // Click confirm button
      const confirmButton = screen.getByTestId('confirm-button');
      fireEvent.click(confirmButton);

      await waitFor(() => {
        expect(mockToast).toHaveBeenCalledWith({
          title: "Success",
          description: "Lawn Mowing removed successfully"
        });
      });

      // Verify the item is removed from UI
      await waitFor(() => {
        expect(screen.queryByText('Lawn Mowing')).not.toBeInTheDocument();
        expect(screen.getByText('Tree Trimming')).toBeInTheDocument();
      });
    });

    it('should cancel deletion when cancel button is clicked', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Click remove button - should show confirmation dialog
      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      // Verify confirmation dialog appears
      await waitFor(() => {
        expect(screen.getByTestId('confirmation-dialog')).toBeInTheDocument();
      });

      // Click cancel button
      const cancelButton = screen.getByTestId('cancel-button');
      fireEvent.click(cancelButton);

      // Verify dialog closes and item is still present
      await waitFor(() => {
        expect(screen.queryByTestId('confirmation-dialog')).not.toBeInTheDocument();
      });

      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      expect(screen.getByText('Tree Trimming')).toBeInTheDocument();

      // Verify no deletion occurred
      expect(global.fetch).not.toHaveBeenCalledWith(
        expect.stringContaining('/api/quotes/'),
        expect.objectContaining({ method: 'DELETE' })
      );
    });

    it('should handle deletion failure and revert UI', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Click remove button and confirm
      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      await waitFor(() => {
        expect(screen.getByTestId('confirmation-dialog')).toBeInTheDocument();
      });

      // Mock failed deletion
      (global.fetch as jest.Mock).mockResolvedValueOnce({
        ok: false,
        status: 500
      });

      fireEvent.click(screen.getByTestId('confirm-button'));

      await waitFor(() => {
        expect(mockToast).toHaveBeenCalledWith({
          title: "Error",
          description: "Failed to remove Lawn Mowing. Please try again.",
          variant: "destructive"
        });
      });

      // Verify the item is still in the UI
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      expect(screen.getByText('Tree Trimming')).toBeInTheDocument();
    });

    it('should show loading state during deletion', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Click remove and confirm
      const removeButtons = screen.getAllByText('Remove');
      const initialButtonCount = removeButtons.length;
      fireEvent.click(removeButtons[0]);

      await waitFor(() => {
        expect(screen.getByTestId('confirmation-dialog')).toBeInTheDocument();
      });

      // Mock a delayed response
      let resolvePromise: ((value: any) => void) | undefined;
      const delayedPromise = new Promise((resolve) => {
        resolvePromise = resolve;
      });

      (global.fetch as jest.Mock).mockReturnValueOnce(delayedPromise);

      fireEvent.click(screen.getByTestId('confirm-button'));

      // The item should be optimistically removed, so we should have one less remove button
      await waitFor(() => {
        const currentButtons = screen.getAllByText('Remove');
        expect(currentButtons.length).toBe(initialButtonCount - 1);
      });

      // Resolve the promise
      resolvePromise?.({
        ok: true,
        json: async () => ({
          ok: true,
          quote: mockQuote,
          lineItems: [mockLineItems[1]]
        })
      });

      // Wait for the toast to appear
      await waitFor(() => {
        expect(mockToast).toHaveBeenCalledWith(expect.objectContaining({
          title: "Success"
        }));
      });
    });

    it('should handle network errors gracefully', async () => {
      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Click remove and confirm
      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      await waitFor(() => {
        expect(screen.getByTestId('confirmation-dialog')).toBeInTheDocument();
      });

      // Mock network error
      (global.fetch as jest.Mock).mockRejectedValueOnce(new Error('Network error'));

      fireEvent.click(screen.getByTestId('confirm-button'));

      await waitFor(() => {
        expect(mockToast).toHaveBeenCalledWith({
          title: "Error",
          description: "Failed to remove Lawn Mowing. Please try again.",
          variant: "destructive"
        });
      });

      // Verify items are still present
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      expect(screen.getByText('Tree Trimming')).toBeInTheDocument();
    });
  });

  describe('Optimistic Updates', () => {
    it('should optimistically remove item from UI immediately', async () => {
      // First mock for initial load
      (global.fetch as jest.Mock) = jest.fn().mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          quote: mockQuote,
          lineItems: mockLineItems
        })
      });

      render(<QuoteViewerPage />);

      // Wait for initial load
      await waitFor(() => {
        expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
      });

      // Mock a slow response for deletion
      const slowPromise = new Promise((resolve) => {
        setTimeout(() => {
          resolve({
            ok: true,
            json: async () => ({
              ok: true,
              quote: mockQuote,
              lineItems: [mockLineItems[1]]
            })
          });
        }, 100);
      });

      (global.fetch as jest.Mock).mockReturnValueOnce(slowPromise);

      const removeButtons = screen.getAllByText('Remove');
      fireEvent.click(removeButtons[0]);

      await waitFor(() => {
        expect(screen.getByTestId('confirmation-dialog')).toBeInTheDocument();
      });

      fireEvent.click(screen.getByTestId('confirm-button'));

      // Item should be removed immediately (optimistic update)
      await waitFor(() => {
        expect(screen.queryByText('Lawn Mowing')).not.toBeInTheDocument();
      }, { timeout: 50 });
    });
  });
});

