              ok: true,
              quote: mockQuote,
              lineItems: [mockLineItems[1]] // Only second item remains
            })
          });
        } else if (url.includes('/api/quotes/')) {
          return Promise.resolve({
            ok: true,
            json: async () => ({ quote: mockQuote, lineItems: mockLineItems })
          });
        } else if (url.includes('/api/services')) {
